/// A start of a family's ladder: the moves of the correct line before it, and which of its two
/// puzzles the test of interest kept - the book's own kind, and the twin.
pub const Start = struct {
    moves: u8,
    own: bool = true,
    twin: bool = true,
};

/// One published problem: its file, its level's name, and the later starts the converter
